public class TransientDemoTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            SessionInfo original = new SessionInfo("bob", "secret");
            SessionInfo copy = TransientDemo.roundTrip(original);
            check("a new object is returned", true, copy != null && copy != original);
            check("user survives", "bob",
                    copy == null ? "(no object)" : copy.getUser());
            check("transient token becomes null", null,
                    copy == null ? "(no object)" : copy.getToken());
            check("original token untouched", "secret", original.getToken());

            SessionInfo copy2 = TransientDemo.roundTrip(new SessionInfo("eve", null));
            check("second user survives", "eve",
                    copy2 == null ? "(no object)" : copy2.getUser());
            check("null token stays null", null,
                    copy2 == null ? "(no object)" : copy2.getToken());
        } catch (Exception e) {
            check("round trip completes without exception", "none",
                    e.getClass().getSimpleName());
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

